#{couponId}
order by cm.coupon_id, m.shop_name, cm.merchant_id

select count(1) from shop_merchant where merchant_id in
#{merchantId}
and audit_status = 'APPROVED' and status = '0' and del_flag = '0'

select count(1) from shop_user where user_id in
#{userId}
and status = '0' and del_flag = '0'

select count(1)
from shop_coupon_exchange
where coupon_id = #{couponId} and shop_user_id = #{userId}
